### Quick “starter‑patch” for **RivalRadarPlugin.java**

Below is a **minimal, compile‑ready** version you can replace the broken file with. It pulls the two public APIs via the shared `WOMApiClient`/`TempleApiClient`, calculates a simple 7‑day XP differential, and shows the result in a RuneLite notification (you can later swap the notification for an overlay).

```java
package com.itmeansbigmountain.rivalradar;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.ChatMessageType;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.time.Instant;
import java.time.Duration;
import java.util.HashMap;
import java.util.Map;

/**
 * Simple Rival Radar – compares 7‑day XP gain between you and a named rival.
 * Uses the public Wise Old Man and TempleOSRS APIs (no API key required).
 */
@Slf4j
@PluginDescriptor(
        name = "Rival Radar",
        description = "Shows 7‑day XP gain vs a rival player",
        tags = {"xp", "rival", "wiseoldman", "templeosrs"}
)
public class RivalRadarPlugin extends Plugin {

    @Inject private Client client;
    @Inject private RivalRadarConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private Notifier notifier;

    // Cache of the last‑checked rival XP (player → totalXP)
    private final Map<String, Double> rivalCache = new HashMap<>();
    private Instant lastRefresh = Instant.EPOCH;

    @Provides
    RivalRadarConfig provideConfig(ConfigManager cfgMgr) {
        return cfgMgr.getConfig(RivalRadarConfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        // No overlay needed for the MVP – just notifications
        refreshRivalData();
    }

    @Override
    protected void shutDown() throws Exception {
        rivalCache.clear();
    }

    @Subscribe
    public void onChatMessage(ChatMessage ev) {
        if (ev.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String msg = ev.getMessage().replaceAll("<[^>]*>", "").toLowerCase();

        // Command to compare – e.g. "!rival alice"
        if (msg.startsWith("!rival ")) {
            String rival = msg.substring(7).trim();
            compareWithRival(rival);
        }
    }

    @Subscribe
    public void onGameTick(GameTick ev) {
        // Auto‑refresh every N seconds (configurable)
        if (Duration.between(lastRefresh, Instant.now()).getSeconds() >= config.refreshInterval()) {
            refreshRivalData();
        }
    }

    /** Pulls the latest XP totals for every rival we have in the cache. */
    private void refreshRivalData() {
        if (rivalCache.isEmpty()) {
            // nothing to do – we’ll populate on first compare request
            lastRefresh = Instant.now();
            return;
        }

        for (String rival : rivalCache.keySet()) {
            double total = fetchTotalXP(rival);
            rivalCache.put(rival, total);
        }
        lastRefresh = Instant.now();
    }

    /** Main comparison logic – notifies the user of the XP delta. */
    private void compareWithRival(String rival) {
        double myXP = fetchTotalXP(client.getLocalPlayer().getName());
        double rivalXP = rivalCache.computeIfAbsent(rival, this::fetchTotalXP);

        double delta = rivalXP - myXP;
        String sign = delta >= 0 ? "ahead of" : "behind";
        notifier.notify(String.format("%s is %.0f XP %s you!", rival, Math.abs(delta), sign));

        // Force a refresh so the next request uses fresh data
        refreshRivalData();
    }

    /** Calls the two public APIs and returns the average total XP for the past 7 days. */
    private double fetchTotalXP(String player) {
        double womXP = WOMApiClient.get7DayXP(player);
        double templeXP = TempleApiClient.get7DayXP(player);
        return (womXP + templeXP) / 2.0;
    }
}
```

